const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start = ee.Date('2022-07-19');
    const end = start.advance(1, 'day');
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level0');
    const uk = gaul.filter(ee.Filter.eq('ADM0_NAME', 'United Kingdom')).geometry().buffer(0);

    // 2. Data Acquisition & Check
    let col = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
      .filterDate(start, end)
      .select('temperature_2m');
    let size = await col.size().getInfo();

    if (size === 0) {
      // Fallback to ERA5 (non-land) hourly if LAND is empty
      col = ee.ImageCollection('ECMWF/ERA5/HOURLY')
        .filterDate(start, end)
        .select('temperature_2m');
      size = await col.size().getInfo();
      if (size === 0) {
        console.log('ERA5-LAND HOURLY Images: 0');
        console.log('ERA5 HOURLY Images: 0');
        console.log('No data for the specified date/location.');
        console.log('C1');
        return;
      } else {
        console.log(`ERA5-LAND HOURLY Images: 0`);
        console.log(`ERA5 HOURLY Images: ${size}`);
      }
    } else {
      console.log(`ERA5-LAND HOURLY Images: ${size}`);
    }

    // 3. Processing: get daily maximum 2m air temperature (K)
    const imgMax = col.max(); // band: 'temperature_2m'
    const scale = 10000; // 10 km to ensure performance and avoid timeout

    // Pixel count validation
    const countDict = await imgMax.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: uk,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const bandName = 'temperature_2m';
    const pixelCount = countDict ? countDict[bandName] : null;
    console.log(`Valid Pixels: ${pixelCount !== null ? pixelCount : 0}`);

    if (!pixelCount || pixelCount === 0) {
      console.log('No valid pixels after processing.');
      console.log('C2');
      return;
    }

    // 4. Calculation: regional maximum
    const maxDict = await imgMax.reduceRegion({
      reducer: ee.Reducer.max(),
      geometry: uk,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const maxK = maxDict ? maxDict[bandName] : null;
    if (maxK === null || maxK === undefined || isNaN(maxK)) {
      console.log('Calculation produced null/NaN.');
      console.log('C3');
      return;
    }

    const maxC = maxK - 273.15;
    const maxF = (maxC * 9) / 5 + 32;
    console.log(`Date (UTC): 2022-07-19`);
    console.log(`Max Temp: ${maxK.toFixed(2)} K | ${maxC.toFixed(2)} °C | ${maxF.toFixed(2)} °F`);

    // 5. Final Answer
    if (!isFinite(maxF)) {
      console.log('C3');
    } else if (maxF > 100.0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${String(err).slice(0, 200)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
